// =========================================================================
// 🧠 DAY-OF-WEEK CADENCE & ANTI-REPETITION MEMORY ENGINE
// =========================================================================
const staticData = $getWorkflowStaticData('global');
staticData.topicHistory = staticData.topicHistory || [];

const settings = $input.item.json;
const now = new Date();
const currentHour = now.getHours();
const currentDay = now.getDay(); // 0 = Sun, 1 = Mon, ..., 5 = Fri, 6 = Sat

// 1. Daily Archetype System (keeps content varied & captivating every day)
const archetypeSchedule = {
  1: { archetype: "TACTICAL_PLAYBOOK", focus: "A high-leverage rule of thumb, architectural pattern, or code smell that saves hours in production." },
  2: { archetype: "ARCHITECTURE_TEARDOWN", focus: "Dissecting a core stack debate: e.g. Postgres vs specialized DBs, Monolith vs Microservices, SSR vs SPA." },
  3: { archetype: "PRODUCTION_WAR_STORY", focus: "A realistic production outage or tech debt horror story: what broke, why it broke, and the real fix." },
  4: { archetype: "HIDDEN_TRADEOFFS", focus: "Exposing the hidden costs of hype: serverless billing traps, premature abstractions, or over-engineered CI/CD." },
  5: { archetype: "POLARIZING_DEBATE", focus: "A spicy, contrarian engineering take that challenges common wisdom and forces members to pick a side." },
  6: { archetype: "FUTURE_HORIZONS", focus: "Local AI tooling, edge compute, or unconventional open-source tech worth watching." },
  0: { archetype: "DEEP_CRAFT_REFLECT", focus: "Software craftsmanship, avoiding burnout, and what separates 10x codebases from unmaintainable sludge." }
};

const scheduled = archetypeSchedule[currentDay] || archetypeSchedule[1];
const selectedArchetype = (settings.contentArchetype && settings.contentArchetype !== "AUTO_ROTATE")
  ? settings.contentArchetype
  : scheduled.archetype;

// 2. Slot Context: Morning Kickstart vs Evening Roundtable
let slotType, slotTheme, shouldIncludePoll;
if (currentHour < 13) {
  slotType = "MORNING_BRIEF";
  slotTheme = `MORNING INTEL: High-signal briefing for engineers starting their day. Focus: ${scheduled.focus}`;
  shouldIncludePoll = false;
} else {
  slotType = "EVENING_ROUNDTABLE";
  slotTheme = `EVENING ROUNDTABLE: Relaxed, engaging end-of-day discussion for tech builders. Focus: ${scheduled.focus} Includes an interactive poll sparking peer debate.`;
  shouldIncludePoll = settings.enablePolls !== false;
}

// 3. Sliding Memory (Anti-Repetition)
const recentTopics = staticData.topicHistory.slice(-30);

// 4. Topic Inspiration Pool
const priorityList = Array.isArray(settings.priorityTopics) && settings.priorityTopics.length > 0
  ? settings.priorityTopics.join("\n- ")
  : "General high-signal engineering & systems design";

return [{
  json: {
    ...settings,
    activeArchetype: selectedArchetype,
    slotType,
    slotTheme,
    shouldIncludePoll,
    priorityTopicList: priorityList,
    recentTopicsList: recentTopics.length > 0 ? recentTopics.join("\n- ") : "None yet (First run)"
  }
}];

