// =========================================================================
// 🛡️ SANITIZE WHATSAPP POST & PERSISTENT MEMORY
// =========================================================================
const staticData = $getWorkflowStaticData('global');
staticData.topicHistory = staticData.topicHistory || [];

const rawOutput = $input.item.json.output || $input.item.json.text || "";
const settings = $('⚙️ Community Bot Settings').item.json;
const memoryCtx = $('🧠 Memory & Day Cadence Engine').item.json;

let parsed;
try {
  const cleaned = rawOutput.replace(/```json/gi, '').replace(/```/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = {
    topic: "Community Strategy Update",
    caption: rawOutput,
    poll: null
  };
}

// 1. WhatsApp Markdown Sanitizer
let caption = parsed.caption || rawOutput;
caption = caption
  .replace(/\*\*(.*?)\*\*/g, '*$1*') // Convert **bold** to *bold*
  .replace(/^#+\s*/gm, '')           // Strip markdown # headers
  .replace(/\[([^\]]+)\]\(([^)]+)\)/g, '$1: $2') // Convert [Link](url) to Link: url
  .replace(/^>([^\s])/gm, '> $1');   // Ensure WhatsApp quote bar has space after >

// 2. Validate Poll Payload
let validPoll = null;
if (settings.enablePolls && parsed.poll && parsed.poll.question && Array.isArray(parsed.poll.options) && parsed.poll.options.length >= 2) {
  validPoll = {
    question: String(parsed.poll.question).slice(0, 255),
    options: parsed.poll.options.slice(0, 4).map(opt => String(opt).trim().slice(0, 80)),
    multiSelect: settings.pollMultiSelect !== undefined ? Boolean(settings.pollMultiSelect) : Boolean(parsed.poll.multiSelect)
  };
}

// 3. Save to Anti-Repetition Persistent Memory
if (parsed.topic) {
  staticData.topicHistory.push(parsed.topic);
  if (staticData.topicHistory.length > 30) {
    staticData.topicHistory.shift();
  }
}

return [{
  json: {
    topic: parsed.topic,
    caption: caption,
    recipient: settings.recipient || "YOUR_GROUP_OR_CHANNEL_JID@g.us",
    hasPoll: Boolean(validPoll),
    poll: validPoll
  }
}];
